import '@testing-library/jest-dom/vitest'

import { fireEvent, render, screen, waitFor } from '@testing-library/react'
import { MemoryRouter } from 'react-router-dom'
import { describe, expect, it, vi } from 'vitest'

const mocks = vi.hoisted(() => ({ getFamilyDashboard: vi.fn() }))
vi.mock('../../services/apiClient', () => ({ threePortalApi: mocks }))

import { EmergencyHelp } from '../dashboard/dashboardParts'
import { FamilyDashboardPanel } from './FamilyDashboardPanel'

const baseDashboard = {
  role: 'Head',
  familyName: 'Silva Family',
  familyCode: 'FV-ABCDEF',
  memberCount: 4,
  minorCount: 2,
  pendingJoinRequests: 3,
  nextAppointment: null,
  openCases: 1,
  approvedGuidanceCount: 2,
  familyDoctor: null,
  unreadNotifications: 0,
  recentActivity: [],
}

describe('FamilyDashboardPanel (Head)', () => {
  it('opens the upload workflow and approved guidance from dashboard actions', async () => {
    mocks.getFamilyDashboard.mockResolvedValue({ data: baseDashboard })
    render(
      <MemoryRouter>
        <FamilyDashboardPanel />
      </MemoryRouter>,
    )
    expect(await screen.findByRole('link', { name: /Upload Report/ })).toHaveAttribute(
      'href',
      '/records?tab=labs&upload=1',
    )
    expect(screen.getByRole('link', { name: 'Read guidance' })).toHaveAttribute(
      'href',
      '/triage?view=guidance',
    )
  })

  it('refreshes server summaries when returning to the dashboard tab', async () => {
    mocks.getFamilyDashboard
      .mockResolvedValueOnce({ data: { ...baseDashboard, recentActivity: [] } })
      .mockResolvedValueOnce({ data: { ...baseDashboard, recentActivity: ['Doctor review completed'] } })
    render(
      <MemoryRouter>
        <FamilyDashboardPanel />
      </MemoryRouter>,
    )
    await screen.findByText('Family Members')
    fireEvent(window, new Event('focus'))
    expect(await screen.findByText('Doctor review completed')).toBeInTheDocument()
  })

  it('renders the mockup metrics: members, cases and join requests', async () => {
    mocks.getFamilyDashboard.mockResolvedValue({ data: baseDashboard })

    render(
      <MemoryRouter>
        <FamilyDashboardPanel />
      </MemoryRouter>,
    )

    await waitFor(() => expect(screen.getByText('Family Members')).toBeInTheDocument())
    expect(screen.getByText('4')).toBeInTheDocument()
    expect(screen.getByText('Join Requests')).toBeInTheDocument()
    expect(screen.getByText('3 join requests')).toBeInTheDocument()
    expect(screen.getByText('+ Add Minor')).toBeInTheDocument()
    expect(screen.getByText(/FV-ABCDEF/)).toBeInTheDocument()
  })

  it('renders recent activity strings from older API builds', async () => {
    mocks.getFamilyDashboard.mockResolvedValue({
      data: { ...baseDashboard, recentActivity: ['Appointment requested'] },
    })

    render(
      <MemoryRouter>
        <FamilyDashboardPanel />
      </MemoryRouter>,
    )

    expect(await screen.findByText('Appointment requested')).toBeInTheDocument()
  })

  it('shows member cards exactly as the API summarises them', async () => {
    mocks.getFamilyDashboard.mockResolvedValue({
      data: {
        ...baseDashboard,
        members: [
          {
            id: 'm1',
            displayName: 'Nimal Perera',
            role: 'Head',
            isSelf: true,
            isMinor: false,
            summary: 'You · 1 upcoming appointment',
          },
          {
            id: 'm2',
            displayName: 'Amaya Perera',
            role: 'AdultMember',
            isSelf: false,
            isMinor: false,
            summary: 'Adult · private by default',
          },
          {
            id: 'm3',
            displayName: 'Kasun Perera',
            role: 'MinorMember',
            isSelf: false,
            isMinor: true,
            summary: 'Guardian managed · no upcoming appointments',
          },
        ],
        activity: [{ title: 'Case updated', subject: 'Kasun Perera', occurredAt: '2026-09-22T10:00:00Z' }],
      },
    })

    render(
      <MemoryRouter>
        <FamilyDashboardPanel />
      </MemoryRouter>,
    )

    expect(await screen.findByText('Adult · private by default')).toBeInTheDocument()
    expect(screen.getByText('Minor')).toBeInTheDocument()
    expect(screen.getByText('Case updated')).toBeInTheDocument()
  })

  it('shows an emergency referral card, not a browser alert', async () => {
    // Emergency Help now lives in AppLayout so it is on every family page (RULE 10).
    render(<EmergencyHelp />)
    ;(await screen.findByText('Emergency Help')).click()
    expect(await screen.findByText(/call 1990/i)).toBeInTheDocument()
  })
})
